insert into public.qcms (id, course_id, module_id, type, stem, explanation, difficulty, source, tags, status) values
  ('00000000-0000-4000-8004-000000000001', '00000000-0000-4000-8003-000000000001', '00000000-0000-4000-8001-000000000001', 'multiple', 'Concernant la scapula (omoplate) :', 'La scapula est un os plat triangulaire de la ceinture scapulaire. Sa face postérieure porte l’épine, qui se prolonge latéralement par l’acromion (articulé avec la clavicule). La cavité glénoïdale reçoit la tête humérale.', 2, null, array['ostéologie', 'membre supérieur'], 'published'),
  ('00000000-0000-4000-8004-000000000002', '00000000-0000-4000-8003-000000000001', '00000000-0000-4000-8001-000000000001', 'single', 'Quel os du carpe s’articule avec le radius et est le plus fréquemment fracturé ?', 'Le scaphoïde (rangée proximale) s’articule avec le radius. Sa fracture, typique d’une chute sur la paume de la main, poignet en extension, expose au risque de nécrose du pôle proximal.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000003', '00000000-0000-4000-8003-000000000001', '00000000-0000-4000-8001-000000000001', 'multiple', 'Concernant l’humérus :', 'Deux rapports nerveux à connaître : nerf radial (sillon postérieur de la diaphyse, exposé dans les fractures diaphysaires) et nerf ulnaire (derrière l’épicondyle médial). Le col chirurgical, sous les tubercules, est le siège fréquent des fractures du sujet âgé.', 3, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000004', '00000000-0000-4000-8003-000000000002', '00000000-0000-4000-8001-000000000002', 'multiple', 'Concernant le glucose :', 'Le D-glucose est un aldohexose (C6H12O6). En solution aqueuse, la forme linéaire est minoritaire : la cyclisation hémiacétalique donne surtout le β-D-glucopyranose.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000005', '00000000-0000-4000-8003-000000000003', '00000000-0000-4000-8001-000000000002', 'single', 'Quel acide aminé ne possède pas de carbone asymétrique ?', 'La chaîne latérale de la glycine est un atome d’hydrogène : son carbone α porte deux H, il n’est donc pas chiral.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000006', '00000000-0000-4000-8003-000000000003', '00000000-0000-4000-8001-000000000002', 'multiple', 'La liaison peptidique :', 'Condensation entre COOH α et NH2 α avec départ d’eau. La délocalisation électronique donne à la liaison C–N un caractère partiel de double liaison : le groupement peptidique est plan, sans rotation libre.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000007', '00000000-0000-4000-8003-000000000007', '00000000-0000-4000-8001-000000000006', 'multiple', 'Concernant la membrane plasmique :', 'Bicouche de phospholipides amphiphiles dans laquelle diffusent protéines et cholestérol (mosaïque fluide). L’asymétrie membranaire place les glycolipides et glycoprotéines sur la face externe.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000008', '00000000-0000-4000-8003-000000000008', '00000000-0000-4000-8001-000000000006', 'single', 'Quel organite est le siège de la phosphorylation oxydative ?', 'La chaîne respiratoire et l’ATP synthase sont localisées dans la membrane interne mitochondriale (crêtes).', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000009', '00000000-0000-4000-8003-000000000009', '00000000-0000-4000-8001-000000000006', 'multiple', 'Au cours de la mitose :', 'Prophase → prométaphase → métaphase → anaphase → télophase. La mitose conserve la ploïdie ; la réduction chromosomique est le fait de la méiose.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000010', '00000000-0000-4000-8003-000000000012', '00000000-0000-4000-8001-000000000009', 'multiple', 'Le potentiel de repos d’un neurone :', 'Au repos, la membrane est surtout perméable au K+ : le potentiel de repos est proche du potentiel d’équilibre du potassium. La pompe Na+/K+ (électrogène) maintient les gradients.', 3, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000011', '00000000-0000-4000-8003-000000000013', '00000000-0000-4000-8001-000000000009', 'single', 'Quelle hormone est hypoglycémiante ?', 'L’insuline (cellules β des îlots de Langerhans) est la seule hormone hypoglycémiante ; les autres citées sont hyperglycémiantes.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000012', '00000000-0000-4000-8003-000000000004', '00000000-0000-4000-8001-000000000003', 'single', 'L’unité de pression du Système international est :', '1 Pa = 1 N·m⁻². Le mmHg et le cmH2O restent utilisés en médecine mais ne sont pas des unités SI.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000013', '00000000-0000-4000-8003-000000000005', '00000000-0000-4000-8001-000000000003', 'multiple', 'Concernant l’osmolarité et les solutions :', 'L’osmolarité est une propriété colligative : elle dépend du nombre de particules en solution. L’eau se déplace vers le compartiment le plus concentré en osmoles efficaces.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000014', '00000000-0000-4000-8003-000000000010', '00000000-0000-4000-8001-000000000007', 'multiple', 'Concernant la fécondation humaine :', 'L’ovocyte est bloqué en métaphase II jusqu’à la fécondation. La réaction corticale modifie la zone pellucide et bloque la polyspermie.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000015', '00000000-0000-4000-8003-000000000011', '00000000-0000-4000-8001-000000000008', 'single', 'L’épiderme est un épithélium :', 'Épithélium malpighien kératinisé : couches basale, épineuse, granuleuse et cornée.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000016', '00000000-0000-4000-8003-000000000006', '00000000-0000-4000-8001-000000000004', 'single', 'Pour une variable suivant une loi normale, l’intervalle moyenne ± 1,96 écart-type contient environ :', 'μ ± 1σ ≈ 68 %, μ ± 1,96σ ≈ 95 %, μ ± 2,58σ ≈ 99 %, μ ± 3σ ≈ 99,7 %.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000017', '00000000-0000-4000-8003-000000000014', '00000000-0000-4000-8001-000000000011', 'multiple', 'Concernant le cœur :', 'Le ventricule gauche, qui éjecte dans la circulation systémique à haute pression, a la paroi la plus épaisse. Le nœud sinusal, près de l’abouchement de la veine cave supérieure, est le pacemaker physiologique.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000018', '00000000-0000-4000-8003-000000000015', '00000000-0000-4000-8001-000000000011', 'single', 'Le débit cardiaque est égal à :', 'Qc = FC × VES (≈ 70 × 70 mL ≈ 5 L/min au repos). À noter : PAM = Qc × RVS.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000019', '00000000-0000-4000-8003-000000000016', '00000000-0000-4000-8001-000000000011', 'multiple', 'Le surfactant pulmonaire :', 'Mélange de phospholipides (surtout dipalmitoylphosphatidylcholine) et de protéines, il stabilise les alvéoles et prévient leur collapsus en fin d’expiration.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000020', '00000000-0000-4000-8003-000000000017', '00000000-0000-4000-8001-000000000012', 'single', 'La sécrétion d’acide chlorhydrique gastrique est assurée par les :', 'Les cellules pariétales sécrètent HCl (pompe H+/K+-ATPase) et le facteur intrinsèque. Les cellules principales sécrètent le pepsinogène, les cellules G la gastrine.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000021', '00000000-0000-4000-8003-000000000018', '00000000-0000-4000-8001-000000000016', 'multiple', 'Concernant les immunoglobulines :', 'Retenir : IgG (placenta, majoritaires), IgM (pentamère, réponse primaire), IgA (muqueuses, dimère sécrétoire), IgE (allergie, parasites), IgD (récepteur du lymphocyte B naïf).', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000022', '00000000-0000-4000-8003-000000000019', '00000000-0000-4000-8001-000000000017', 'single', 'Le caryotype humain normal comporte :', '46 chromosomes : 22 paires d’autosomes + 1 paire de gonosomes (46,XX ou 46,XY).', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000023', '00000000-0000-4000-8003-000000000020', '00000000-0000-4000-8001-000000000020', 'single', 'La denture permanente complète comporte :', 'Par hémi-arcade : 2 incisives, 1 canine, 2 prémolaires, 3 molaires = 8, soit 32 dents (dents de sagesse comprises).', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000024', '00000000-0000-4000-8003-000000000021', '00000000-0000-4000-8001-000000000020', 'multiple', 'Concernant l’émail dentaire :', 'Émail ≈ 96 % de minéral (hydroxyapatite). Il dérive de l’organe de l’émail (ectoderme) ; la dentine et la pulpe dérivent de l’ectomésenchyme.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000025', '00000000-0000-4000-8003-000000000020', '00000000-0000-4000-8001-000000000020', 'single', 'La denture temporaire (lactéale) comporte :', 'Par hémi-arcade : 2 incisives, 1 canine, 2 molaires temporaires = 5, soit 20 dents. Il n’y a pas de prémolaires temporaires.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000026', '00000000-0000-4000-8003-000000000022', '00000000-0000-4000-8001-000000000024', 'single', 'La synthèse des protéines destinées à être sécrétées débute sur les ribosomes et se poursuit dans :', 'Voie de sécrétion : ribosomes liés au REG → appareil de Golgi → vésicules de sécrétion → exocytose.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000027', '00000000-0000-4000-8003-000000000025', '00000000-0000-4000-8001-000000000031', 'multiple', 'Concernant la dentine :', 'La dentine (≈ 70 % minéral) forme la masse de la dent ; les prolongements odontoblastiques occupent les tubules, ce qui explique la sensibilité dentinaire.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000028', '00000000-0000-4000-8003-000000000023', '00000000-0000-4000-8001-000000000030', 'single', 'Parmi ces muscles, lequel est élévateur de la mandibule ?', 'Élévateurs : masséter, temporal, ptérygoïdien médial. Le ptérygoïdien latéral est propulseur ; les sus-hyoïdiens (digastrique, mylo- et génio-hyoïdien) sont abaisseurs.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000029', '00000000-0000-4000-8003-000000000024', '00000000-0000-4000-8001-000000000030', 'single', 'La sensibilité des dents mandibulaires est assurée par le nerf :', 'Branche du nerf mandibulaire (V3), le nerf alvéolaire inférieur chemine dans le canal mandibulaire ; c’est la cible de l’anesthésie tronculaire à l’épine de Spix.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000030', '00000000-0000-4000-8003-000000000026', '00000000-0000-4000-8001-000000000039', 'single', 'Le numéro atomique Z d’un élément représente :', 'Z = nombre de protons (égal au nombre d’électrons de l’atome neutre). A = nombre de nucléons = Z + N.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000031', '00000000-0000-4000-8003-000000000027', '00000000-0000-4000-8001-000000000039', 'multiple', 'Concernant le pH :', 'L’échelle de pH est logarithmique : une unité de pH correspond à un facteur 10 de [H3O+]. Le pH artériel normal est de 7,38–7,42.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000032', '00000000-0000-4000-8003-000000000029', '00000000-0000-4000-8001-000000000044', 'multiple', 'La cellule végétale :', 'Trois particularités de la cellule végétale : paroi, plastes, grande vacuole. Elle conserve toutefois des mitochondries.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000033', '00000000-0000-4000-8003-000000000028', '00000000-0000-4000-8001-000000000040', 'single', 'Un atome de carbone hybridé sp3 présente une géométrie :', 'sp3 : 4 orbitales hybrides à 109,5° (tétraèdre, ex. méthane). sp2 : plan trigonal à 120°. sp : linéaire à 180°.', 1, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000034', '00000000-0000-4000-8003-000000000030', '00000000-0000-4000-8001-000000000048', 'single', 'Dans le modèle de Michaelis-Menten, la constante Km correspond à :', 'Km s’exprime en concentration ; plus Km est faible, plus l’affinité apparente de l’enzyme pour son substrat est grande.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000035', '00000000-0000-4000-8003-000000000032', '00000000-0000-4000-8001-000000000051', 'multiple', 'Concernant les bactéries à Gram positif :', 'Le peptidoglycane épais retient le complexe violet de gentiane–lugol malgré la décoloration à l’alcool : les Gram positif restent violets, les Gram négatif sont recolorés en rose par la fuchsine.', 2, null, '{}', 'published'),
  ('00000000-0000-4000-8004-000000000036', '00000000-0000-4000-8003-000000000031', '00000000-0000-4000-8001-000000000049', 'single', 'Selon la loi de Beer-Lambert, l’absorbance A s’écrit :', 'A = log(I0/I) = ε·l·c, avec ε le coefficient d’absorption molaire, l le trajet optique et c la concentration. Relation linéaire valable pour les solutions diluées.', 1, null, '{}', 'published');
insert into public.qcm_options (qcm_id, label, body, is_correct, explanation) values
  ('00000000-0000-4000-8004-000000000001', 'A', 'C’est un os plat de forme triangulaire', true, null),
