  ('00000000-0000-4000-8004-000000000003', 'A', 'Le nerf radial chemine dans le sillon du nerf radial, à la face postérieure de la diaphyse', true, null),
  ('00000000-0000-4000-8004-000000000003', 'B', 'Le nerf ulnaire passe en arrière de l’épicondyle médial', true, null),
  ('00000000-0000-4000-8004-000000000003', 'C', 'Le col chirurgical est situé au-dessus des tubercules majeur et mineur', false, 'Il est situé sous les tubercules ; le col anatomique borde la tête.'),
  ('00000000-0000-4000-8004-000000000003', 'D', 'Le tubercule majeur est situé en dedans du tubercule mineur', false, 'Le tubercule majeur est latéral.'),
  ('00000000-0000-4000-8004-000000000003', 'E', 'La trochlée humérale s’articule avec l’incisure trochléaire de l’ulna', true, null),
  ('00000000-0000-4000-8004-000000000004', 'A', 'C’est un aldohexose', true, null),
  ('00000000-0000-4000-8004-000000000004', 'B', 'Sa formule brute est C6H12O6', true, null),
  ('00000000-0000-4000-8004-000000000004', 'C', 'C’est un cétose', false, 'Le fructose est un cétose ; le glucose porte une fonction aldéhyde.'),
  ('00000000-0000-4000-8004-000000000004', 'D', 'En solution, il existe majoritairement sous forme cyclique', true, 'Principalement sous forme pyranose (β > α).'),
  ('00000000-0000-4000-8004-000000000004', 'E', 'Le saccharose est formé de deux molécules de glucose', false, 'Saccharose = glucose + fructose ; le maltose = glucose + glucose.'),
