  ('00000000-0000-4000-8004-000000000005', 'E', 'Leucine', false, null),
  ('00000000-0000-4000-8004-000000000006', 'A', 'S’établit entre le carboxyle α d’un acide aminé et l’amine α du suivant', true, null),
  ('00000000-0000-4000-8004-000000000006', 'B', 'Libère une molécule d’eau lors de sa formation', true, null),
  ('00000000-0000-4000-8004-000000000006', 'C', 'Présente un caractère partiel de double liaison', true, null),
  ('00000000-0000-4000-8004-000000000006', 'D', 'Permet une libre rotation autour de la liaison C–N', false, 'La mésomérie rend la liaison C–N plane et rigide.'),
  ('00000000-0000-4000-8004-000000000006', 'E', 'Peut être rompue par hydrolyse', true, null),
  ('00000000-0000-4000-8004-000000000007', 'A', 'Son organisation est décrite par le modèle de la mosaïque fluide (Singer et Nicolson)', true, null),
  ('00000000-0000-4000-8004-000000000007', 'B', 'Les phospholipides sont des molécules amphiphiles', true, null),
  ('00000000-0000-4000-8004-000000000007', 'C', 'Le cholestérol module sa fluidité', true, null),
  ('00000000-0000-4000-8004-000000000007', 'D', 'Les glucides membranaires sont situés sur la face cytosolique', false, 'Ils forment le glycocalyx, sur la face extracellulaire.'),
  ('00000000-0000-4000-8004-000000000007', 'E', 'Les protéines intrinsèques traversent toujours toute la bicouche', false, 'Certaines sont seulement ancrées dans un feuillet.'),
