  ('00000000-0000-4000-8004-000000000009', 'A', 'La prophase est marquée par la condensation des chromosomes', true, null),
  ('00000000-0000-4000-8004-000000000009', 'B', 'En métaphase, les chromosomes s’alignent sur la plaque équatoriale', true, null),
  ('00000000-0000-4000-8004-000000000009', 'C', 'L’anaphase correspond à la séparation des chromatides sœurs', true, null),
  ('00000000-0000-4000-8004-000000000009', 'D', 'Des crossing-over se produisent en prophase', false, 'Les crossing-over sont propres à la prophase I de méiose.'),
  ('00000000-0000-4000-8004-000000000009', 'E', 'Elle aboutit à deux cellules filles haploïdes', false, 'La mitose donne deux cellules diploïdes identiques.'),
  ('00000000-0000-4000-8004-000000000010', 'A', 'Est d’environ −70 mV', true, null),
  ('00000000-0000-4000-8004-000000000010', 'B', 'Dépend principalement de la perméabilité membranaire au K+', true, null),
  ('00000000-0000-4000-8004-000000000010', 'C', 'Est entretenu par la pompe Na+/K+-ATPase, qui fait sortir 3 Na+ et entrer 2 K+', true, null),
  ('00000000-0000-4000-8004-000000000010', 'D', 'Correspond à un intérieur cellulaire positif par rapport à l’extérieur', false, null),
  ('00000000-0000-4000-8004-000000000010', 'E', 'Est aboli par la tétrodotoxine', false, 'La TTX bloque les canaux Na+ voltage-dépendants : elle abolit le potentiel d’action, pas le potentiel de repos.'),
