  ('00000000-0000-4000-8004-000000000013', 'A', 'Une solution de NaCl à 9 g/L est isotonique au plasma', true, null),
  ('00000000-0000-4000-8004-000000000013', 'B', 'L’osmolarité plasmatique normale est d’environ 290 mOsm/L', true, null),
  ('00000000-0000-4000-8004-000000000013', 'C', 'Dans une solution hypotonique, les hématies peuvent subir une hémolyse', true, null),
  ('00000000-0000-4000-8004-000000000013', 'D', 'Dans une solution hypertonique, les hématies gonflent', false, 'Elles perdent de l’eau et se ratatinent (crénelure).'),
  ('00000000-0000-4000-8004-000000000013', 'E', 'L’osmolarité dépend de la masse molaire du soluté et non du nombre de particules', false, 'C’est l’inverse : seule compte la concentration en particules.'),
  ('00000000-0000-4000-8004-000000000014', 'A', 'Elle a lieu normalement dans l’ampoule de la trompe utérine', true, null),
  ('00000000-0000-4000-8004-000000000014', 'B', 'La réaction acrosomique permet la traversée de la zone pellucide', true, null),
